import numpy as np
import numba


def py_union1d(a, b):
    return np.union1d(a, b)


@numba.njit
def union1d_njit(a, b):
    return np.union1d(a, b)


def test_union1d_nan_dedup_matches_python():
    a = np.array([np.nan])
    b = np.array([np.nan])
    got = union1d_njit(a, b)
    expected = py_union1d(a, b)
    # Transition is decided by this assertion: buggy revision will fail
    np.testing.assert_equal(got, expected)


